func (m mailingMods) WithParentsCascading() MailingMod {
	return MailingModFunc(func(ctx context.Context, o *MailingTemplate) {
		if isDone, _ := mailingWithParentsCascadingCtx.Value(ctx); isDone {
			return
		}
		ctx = mailingWithParentsCascadingCtx.WithValue(ctx, true)
		{

			related := o.f.NewUserProfileWithContext(ctx, UserProfileMods.WithParentsCascading())
			m.WithCreatedByUserUserProfile(related).Apply(ctx, o)
		}
		{

			related := o.f.NewMailDomainWithContext(ctx, MailDomainMods.WithParentsCascading())
			m.WithDomainMailDomain(related).Apply(ctx, o)
		}
		{

			related := o.f.NewMailListWithContext(ctx, MailListMods.WithParentsCascading())
			m.WithListMailList(related).Apply(ctx, o)
		}
		{

			related := o.f.NewMailTemplateWithContext(ctx, MailTemplateMods.WithParentsCascading())
			m.WithTemplateMailTemplate(related).Apply(ctx, o)
		}
		{

			related := o.f.NewUserProfileWithContext(ctx, UserProfileMods.WithParentsCascading())
			m.WithUpdatedByUserUserProfile(related).Apply(ctx, o)
		}
	})
}

